            else:
                self.images.append(src)
        if tag == 'table':
            self.tables.append('table')
        if tag == 'title':
            self.in_title = True
    def handle_endtag(self, tag):
        pass
    def handle_data(self, data):
        if self.in_title:
            self.title += data
            self.in_title = False

